/**
 * AI reports: written when a session ends, shown only to the right people, and regenerated by
 * interviewers. The writing itself runs with the development sample provider.
 */
import { and, eq, sessionReports } from '@sidebyside/db';
import type { CreateRoomResponse, JoinRoomResponse, SessionReports } from '@sidebyside/shared';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { sampleProvider } from '../ai/provider';
import { runReportJob } from '../ai/summary';
import { createHarness } from '../testing/harness';

let h: Awaited<ReturnType<typeof createHarness>>;
let owner: string;

beforeAll(async () => {
  h = await createHarness({ AI_SUMMARY_PROVIDER: 'sample' });
  owner = await h.signUp('reports-owner@example.test', 'Priya');
});
afterAll(async () => {
  await h.close();
});

async function endedInterview(shareReport: boolean) {
  const { room } = await h.json<CreateRoomResponse>(
    '/api/rooms',
    {
      method: 'POST',
      cookie: owner,
      body: JSON.stringify({
        title: 'Backend round',
        defaultLanguage: 'python',
        shareReportWithCandidate: shareReport,
      }),
    },
    201,
  );
  const guest = await h.json<JoinRoomResponse>(`/api/rooms/${room.slug}/join`, {
    method: 'POST',
    body: JSON.stringify({ displayName: 'Asha', consent: true }),
  });
  h.roomRpc.generateReports.mockClear();
  await h.json(`/api/rooms/${room.id}/end`, { method: 'POST', cookie: owner });
  return { room, token: guest.collabToken! };
}

const statuses = async (roomId: string) =>
  (
    await h.db
      .select({ kind: sessionReports.kind, status: sessionReports.status })
      .from(sessionReports)
      .where(and(eq(sessionReports.roomId, roomId), eq(sessionReports.roundNumber, 1)))
  )
    .map((r) => `${r.kind}:${r.status}`)
    .sort();

const write = (roomId: string) =>
  runReportJob({
    db: h.db,
    provider: sampleProvider(),
    roomId,
    round: 1,
    docs: { sharedNotes: 'shared', privateNotes: 'private', code: { python: 'print(1)' } },
  });

describe('AI reports', () => {
  it('queues both reports when the session ends', async () => {
    const { room } = await endedInterview(false);
    expect(h.roomRpc.generateReports).toHaveBeenCalledTimes(1);
    expect(await statuses(room.id)).toEqual(['candidate:pending', 'interviewer:pending']);
    await write(room.id);
    expect(await statuses(room.id)).toEqual(['candidate:ready', 'interviewer:ready']);
  });

  it('shows the interviewer both reports and keeps them from an unshared candidate', async () => {
    const { room, token } = await endedInterview(false);
    await write(room.id);

    const mine = await h.json<SessionReports>(`/api/rooms/${room.id}/reports`, { cookie: owner });
    expect(mine.enabled).toBe(true);
    expect(mine.interviewer?.status).toBe('ready');
    expect(mine.interviewer?.content?.summary).toContain('Sample');
    expect(mine.candidate?.status).toBe('ready');
    expect(mine.canRegenerate).toBe(true);

    const theirs = await h.json<SessionReports>(`/api/rooms/${room.id}/reports`, { token });
    expect(theirs.interviewer).toBeNull();
    expect(theirs.candidate).toBeNull();
    expect(theirs.canRegenerate).toBe(false);
  });

  it('gives a candidate only their own report when it is shared', async () => {
    const { room, token } = await endedInterview(true);
    await write(room.id);
    const theirs = await h.json<SessionReports>(`/api/rooms/${room.id}/reports`, { token });
    expect(theirs.interviewer).toBeNull();
    expect(theirs.candidate?.status).toBe('ready');
    expect(JSON.stringify(theirs)).not.toContain('private');
  });

  it('lets only the interviewer regenerate, and not while it is running', async () => {
    const { room, token } = await endedInterview(false);
    await write(room.id);
    const asGuest = await h.call(`/api/rooms/${room.id}/reports/regenerate`, {
      method: 'POST',
      token,
    });
    expect(asGuest.status).toBe(403);

    h.roomRpc.generateReports.mockClear();
    await h.json(`/api/rooms/${room.id}/reports/regenerate`, { method: 'POST', cookie: owner });
    expect(h.roomRpc.generateReports).toHaveBeenCalledTimes(1);
    expect(await statuses(room.id)).toEqual(['candidate:pending', 'interviewer:pending']);

    const again = await h.call(`/api/rooms/${room.id}/reports/regenerate`, {
      method: 'POST',
      cookie: owner,
    });
    expect(again.status).toBe(409);
  });
});

describe('AI reports switched off', () => {
  let off: Awaited<ReturnType<typeof createHarness>>;
  beforeAll(async () => {
    off = await createHarness();
  });
  afterAll(async () => {
    await off.close();
  });

  it('writes nothing and tells the pages to hide the feature', async () => {
    const cookie = await off.signUp('reports-off@example.test', 'Ravi');
    const { room } = await off.json<CreateRoomResponse>(
      '/api/rooms',
      { method: 'POST', cookie, body: JSON.stringify({ title: 'R', defaultLanguage: 'python' }) },
      201,
    );
    await off.json(`/api/rooms/${room.id}/end`, { method: 'POST', cookie });
    expect(off.roomRpc.generateReports).not.toHaveBeenCalled();
    const body = await off.json<SessionReports>(`/api/rooms/${room.id}/reports`, { cookie });
    expect(body.enabled).toBe(false);
    expect(body.interviewer).toBeNull();
  });
});
